long long x = 0;
long long y = 0;
long long c = 0;
long long az = 0;
x = a;
y = 1;
c = 1;
az = ((long long) a) * z;
while ((counter++) < 1)
{
  if (!(c < k))
    break;
  c = c + 1;
  x = (x * z) + a;
  y = y * z;
}

return 0;
}


